/// The "System" endpoints of the Dumbbill API. One method per endpoint, named exactly like the operationId in the
/// backend's Swagger manual (`getLiveness`, `getReadiness`). The code is generated by retrofit.
///
/// Both are public: they send no token (`authExtraKey: false`).
library;

import 'package:dio/dio.dart';
import 'package:dumbbill_mobile/core/network/interceptors.dart';
import 'package:dumbbill_mobile/features/system/data/dto/readiness_dto.dart';
import 'package:retrofit/retrofit.dart';

part 'system_api.g.dart';

/// Calls the System endpoints.
@RestApi()
abstract class SystemApi {
  /// Binds the API to a configured [Dio] client.
  factory SystemApi(Dio dio, {String? baseUrl}) = _SystemApi;

  /// operationId `getLiveness`. Permission: public.
  @GET('/healthz')
  @Extra({authExtraKey: false})
  Future<LivenessDto> getLiveness();

  /// operationId `getReadiness`. Permission: public.
  @GET('/readyz')
  @Extra({authExtraKey: false})
  Future<ReadinessDto> getReadiness();
}
